"""
Dana White's Contender Series — Bolão UVR
Streamlit + Supabase
"""
import pandas as pd
import streamlit as st
import streamlit.components.v1 as components
from datetime import datetime, timedelta
from supabase import create_client, Client

# ──────────────────────────────────────────────
# PAGE CONFIG
# ──────────────────────────────────────────────
st.set_page_config(
    page_title="DWCS · Bolão UVR",
    page_icon="🏆",
    layout="centered",
    initial_sidebar_state="collapsed",
)

# ──────────────────────────────────────────────
# SUPABASE
# ──────────────────────────────────────────────
@st.cache_resource
def get_client() -> Client:
    return create_client(
        st.secrets["supabase"]["url"],
        st.secrets["supabase"]["key"],
    )

sb = get_client()

@st.cache_data(ttl=30)
def load_lutas() -> pd.DataFrame:
    res = sb.table("lutas").select("*").order("ordem").execute()
    df = pd.DataFrame(res.data or [])
    if df.empty:
        df = pd.DataFrame(columns=["id","lutador_1","lutador_2","tipo","ordem",
                                   "foto_1","foto_2","band_1","band_2","rec_1","rec_2",
                                   "hist_1","hist_2"])
    if "foto_1" not in df.columns: df["foto_1"] = ""
    if "foto_2" not in df.columns: df["foto_2"] = ""
    if "band_1" not in df.columns: df["band_1"] = ""
    if "band_2" not in df.columns: df["band_2"] = ""
    # cartel (V-D-E) vindo da ESPN; banco sem a migração continua funcionando
    if "rec_1" not in df.columns: df["rec_1"] = ""
    if "rec_2" not in df.columns: df["rec_2"] = ""
    # últimas lutas (JSON) vindas da ESPN, idem
    if "hist_1" not in df.columns: df["hist_1"] = ""
    if "hist_2" not in df.columns: df["hist_2"] = ""
    return df

@st.cache_data(ttl=30)
def load_palpites() -> pd.DataFrame:
    res = sb.table("palpites").select("*").order("luta_id").execute()
    df = pd.DataFrame(res.data or [])
    if df.empty:
        df = pd.DataFrame(columns=["nome","luta_id","palpite","fotn_1","fotn_2","potn_1","potn_2"])
    return df

@st.cache_data(ttl=30)
def load_resultados() -> pd.DataFrame:
    res = sb.table("resultados").select("*").order("luta_id").execute()
    df = pd.DataFrame(res.data or [])
    if df.empty:
        df = pd.DataFrame(columns=["luta_id","vencedor_real","pontos"])
    return df

@st.cache_data(ttl=30)
def load_config() -> dict:
    res = sb.table("config").select("*").eq("id", 1).execute()
    if res.data and len(res.data) > 0:
        return res.data[0]
    return {}

def invalidate_cache():
    load_lutas.clear()
    load_palpites.clear()
    load_resultados.clear()
    load_config.clear()

def fmt_cartel(rec) -> str:
    """'4-1-0' -> '4-1'; '4-1-2' fica igual. Empate só aparece se houver."""
    import re
    partes = re.findall(r"\d+", str(rec or ""))
    if len(partes) < 2:
        return ""
    if len(partes) >= 3 and int(partes[2]) > 0:
        return "-".join(partes[:3])
    return "-".join(partes[:2])

def parse_hist(txt) -> list:
    """hist_1/hist_2 do banco (JSON) -> lista de lutas. Qualquer lixo vira []."""
    import json
    try:
        val = json.loads(txt) if txt else []
        return [h for h in val if isinstance(h, dict) and h.get("r")] if isinstance(val, list) else []
    except Exception:
        return []

